play:flex;flex-direction:column;gap:8px;pointer-events:auto}.action-controls{position:absolute;right:max(22px,env(safe-area-inset-right));bottom:max(20px,env(safe-area-inset-bottom));width:220px;height:165px;pointer-events:none}.control-btn{position:absolute;border:1px solid #f0f3db8c;border-radius:50%;background:#13211edb;box-shadow:0 3px 9px #0007;color:#f8f6df;font:800 9px 'DM Mono';pointer-events:auto;touch-action:none}.control-btn:active,.control-btn.active{background:#c8f05a;color:#1b291a}.control-btn.pass{width:58px;height:58px;left:15px;bottom:7px;border-color:#bbd56d}.control-btn.shoot{width:73px;height:73px;right:6px;bottom:34px;background:#cc6248e8}.control-btn.lob{width:54px;height:54px;right:25px;top:0}.control-btn.tackle{width:54px;height:54px;left:0;top:19px}.left-controls .control-btn{position:static;width:71px;height:37px;border-radius:7px;background:#14221ee8}.left-controls .sprint{border-color:#e4b85e}.left-controls .switch{border-color:#98b3db}.overlay .panel-buttons{display:flex;gap:8px;flex-wrap:wrap}.pause-panel{text-align:center}.pause-panel .panel-buttons{justify-content:center}.pause-panel .danger{border-color:#a95347;color:#ffc1ab}.pause-panel h2{font-size:38px}.pause-panel p{font:11px 'DM Mono'}.pause-panel #pauseExtra{text-align:left;margin-top:14px;font-size:12px;color:#b9c9b8;line-height:1.8}#eventToast{position:absolute;top:19%;left:50%;transform:translate(-50%,-10px);background:#15241fe8;color:#f6f3dd;padding:10px 16px;border-left:3px solid var(--lime);font:800 13px 'Barlow Condensed';letter-spacing:1px;opacity:0;transition:.25s;z-index:3;pointer-events:none}#eventToast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:760px){.menu-screen{padding:14px 16px 10px}.menu-content{grid-template-columns:1fr;gap:10px}.hero-copy{padding:0;display:grid;grid-template-columns:1fr auto;align-items:end}.hero-copy .eyebrow,.hero-copy p,.hero-meta{display:none}.hero-copy h1{font-size:43px;line-height:.78;margin:4px 0 11px}.hero-copy h1 em{display:block}.menu-board{padding:11px 12px 0}.board-header{font-size:8px;margin-bottom:8px}.mode-grid{gap:5px}.mode-card{min-height:53px;padding:6px;gap:5px}.mode-card.featured{min-height:56px}.mode-icon{width:24px;font-size:15px}.mode-card b{font-size:12px}.mode-card small{font-size:8px;margin-top:1px}.board-footer{gap:9px;padding:9px 0}.board-footer button{font-size:8px}.board-footer span{font-size:7px}.menu-top{height:38px}.brand-mark{width:34px;height:34px}.menu-bottom{font-size:6px}.menu-bottom span:last-child{display:none}.sound-toggle{font-size:8px;padding:7px}.scoreboard{left:10px;transform:none;gap:6px;padding:6px 9px;font-size:15px}.scoreboard #clock{padding-left:7px;font-size:10px}.team-tag{font-size:8px}.top-actions{right:8px;gap:3px}.icon-btn{padding:7px;font-size:8px;min-height:30px}.stats-pill{top:48px;left:10px;transform:none;font-size:7px}.touch-controls{height:165px}.stick-zone{width:126px;height:126px;left:12px;bottom:12px}.stick-zone:before{width:116px;height:116px}.stick-base{inset:2px}#stickBase{inset:2px}#stickKnob{width:49px;height:49px;left:calc(50% - 24.5px);top:calc(50% - 24.5px)}.left-controls{left:142px;bottom:20px}.left-controls .control-btn{width:60px;height:31px;font-size:8px}.action-controls{right:10px;width:180px;height:143px;bottom:10px}.control-btn.pass{width:49px;height:49px;left:12px;bottom:4px;font-size:8px}.control-btn.shoot{width:61px;height:61px;right:3px;bottom:26px;font-size:8px}.control-btn.lob{width:46px;height:46px;right:18px;font-size:7px}.control-btn.tackle{width:46px;height:46px;left:0;top:15px;font-size:7px}.panel{padding:24px 18px}.panel h2{font-size:28px}.setup-columns{gap:6px}.team-choice{padding:9px}.setup-actions button{padding:10px 6px;font-size:9px}.editor-grid{grid-template-columns:1fr}.editor-team-list{display:flex;overflow:auto;gap:5px}.editor-team-list button{white-space:nowrap;width:auto}.player-row{grid-template-columns:22px 1fr 55px 62px;padding:5px;font-size:9px}}
