(()=>{'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], canvas=$('#game'),ctx=canvas.getContext('2d',{alpha:false});
const formations={"4-4-2":[[.05,.5],[.19,.18],[.24,.39],[.24,.61],[.19,.82],[.39,.18],[.42,.39],[.42,.61],[.39,.82],[.67,.37],[.67,.63]],"4-3-3":[[.05,.5],[.19,.18],[.24,.39],[.24,.61],[.19,.82],[.42,.25],[.43,.5],[.42,.75],[.69,.2],[.72,.5],[.69,.8]],"4-2-3-1":[[.05,.5],[.19,.18],[.24,.39],[.24,.61],[.19,.82],[.36,.37],[.36,.63],[.55,.2],[.57,.5],[.55,.8],[.73,.5]],"3-5-2":[[.05,.5],[.22,.28],[.22,.5],[.22,.72],[.41,.12],[.4,.31],[.39,.5],[.4,.69],[.41,.88],[.67,.36],[.67,.64]],"5-3-2":[[.05,.5],[.15,.13],[.2,.31],[.22,.5],[.2,.69],[.15,.87],[.43,.28],[.42,.5],[.43,.72],[.68,.37],[.68,.63]]};
const teams=[{name:'AZURE FC',short:'AZU',color:'#53b7f4',dark:'#17629a',crest:'✦',rating:78},{name:'RUBRO SC',short:'RUB',color:'#f36c55',dark:'#a83331',crest:'◆',rating:76},{name:'VERDE ATLÉTICO',short:'VER',color:'#70d476',dark:'#278249',crest:'▲',rating:74},{name:'SOLAR UNITED',short:'SOL',color:'#f2c852',dark:'#bf762b',crest:'☼',rating:77}];
const positions=['GOL','LD','ZAG','ZAG','LE','VOL','MC','MC','ME','ATA','ATA'];
const state={menu:true,mode:'quick',playing:false,paused:false,teams,home:0,away:1,formation:'4-4-2',camera:0,zoom:1,duration:300,time:0,score:[0,0],shots:[0,0],fouls:[0,0],possession:[0,0],user:0,attackDir:1,matchNo:0,career:{name:'NOVA',club:0,rating:62,goals:0},cup:{round:0,wins:0},master:{club:0,budget:900000,season:1},audio:true,commentary:true};
let players=[],ball,keys={},stick={x:0,y:0,active:false,id:null},last=performance.now(),acc=0,toastTimer=0,menuMode='quick',stadium=0,events=0,goalFlash=0;
function load(){try{const s=JSON.parse(localStorage.getItem('pixel-eleven-save')||'{}');Object.assign(state,s);if(s.teams)state.teams=s.teams;}catch{} }
function save(){try{localStorage.setItem('pixel-eleven-save',JSON.stringify({teams:state.teams,camera:state.camera,zoom:state.zoom,duration:state.duration,audio:state.audio,commentary:state.commentary,formation:state.formation,career:state.career,cup:state.cup,master:state.master,matchNo:state.matchNo}));}catch{}}
load();
const W=1800,H=1050,field={x:110,y:100,w:1580,h:850};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),rand=(a,b)=>a+Math.random()*(b-a),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),teamAt=i=>state.teams[i%state.teams.length];
function notify(text){const e=$('#toast');e.textContent=text;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2100)}
function announce(text){const e=$('#eventToast');e.textContent=text;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1900);if(state.commentary&&state.audio&&'speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='pt-BR';u.volume=.45;u.rate=1.15;speechSynthesis.speak(u)}}
function makePlayers(){players=[];for(let side=0;side<2;side++){const team=teamAt(side?state.away:state.home),formation=side? (team.formation||state.formation):state.formation;const spots=formations[formation]||formations['4-4-2'];for(let i=0;i<11;i++){let p=team.roster?.[i]||{};let x=field.x+spots[i][0]*field.w,y=field.y+spots[i][1]*field.h;if(side)x=field.x+field.w-(x-field.x);players.push({id:side*11+i,side,number:i===0?1:i+1,name:p.name||(['MORAES','SILVA','REIS','COSTA','LIMA','ROCHA','NUNES','MELO','SANTOS','DIAS','NOVA'][i]),role:positions[i],x,y,vx:0,vy:0,tx:x,ty:y,stamina:100,pace:p.pace||rand(73,95),pass:p.pass||rand(67,94),shot:p.shot||rand(63,94),strength:p.strength||rand(60,92),dribble:p.dribble||rand(65,94),skill:p.skill||rand(65,94),cool:rand(0,1),yellow:0} );}}
ball={x:field.x+field.w/2,y:field.y+field.h/2,vx:0,vy:0,z:0,vz:0,owner:null,lastSide:-1,spin:0};state.user=players.filter(p=>p.side===0&&p.id!==0).sort((a,b)=>dist(a,ball)-dist(b,ball))[0].id;}
function start(mode){state.mode=mode||menuMode;state.home=state.master.club||state.home;state.away=(state.home+1+Math.floor(Math.random()*(state.teams.length-1)))%state.teams.length;state.time=0;state.score=[0,0];state.shots=[0,0];state.fouls=[0,0];state.possession=[0,0];state.matchNo++;state.playing=true;state.paused=false;state.menu=false;$('#menu').classList.add('hidden');$('#setup').classList.add('hidden');$('#hud').classList.remove('hidden');$('#pausePanel').classList.add('hidden');$('#matchEnd').classList.add('hidden');stadium=(state.matchNo+state.home)%3;makePlayers();announce('A bola vai rolar!');save();}
function finish(){state.playing=false;state.paused=true;$('#finalTitle').textContent=state.score[0]===state.score[1]?'Empate!':state.score[0]>state.score[1]?'Vitória!':'Fim de jogo';$('#finalSummary').textContent=`${teamAt(state.home).name} ${state.score[0]} — ${state.score[1]} ${teamAt(state.away).name}  •  ${state.shots[0]+state.shots[1]} finalizações`;$('#matchEnd').classList.remove('hidden');if(state.mode==='cup'){state.cup.round++;if(state.score[0]>=state.score[1])state.cup.wins++;else state.cup.wins=0;if(state.cup.round>=3){notify(state.cup.wins>=2?'CAMPEÃO DA TAÇA PIXEL!':'Taça Pixel concluída');state.cup.round=0;state.cup.wins=0}}if(state.mode==='master')state.master.budget+=state.score[0]>=state.score[1]?140000:45000;if(state.mode==='career'){state.career.goals+=state.score[0];state.career.rating=Math.min(99,state.career.rating+1)}save();}
function togglePause(){if(!state.playing)return;state.paused=!state.paused;$('#pausePanel').classList.toggle('hidden',!state.paused);if(state.paused){$('#pauseDetail').textContent=`${teamAt(state.home).name} ${state.score[0]} — ${state.score[1]} ${teamAt(state.away).name}`;$('#pauseExtra').textContent='';}}
function nearest(side,x=ball.x,y=ball.y){let best=null,d=1e9;for(const p of players)if(p.side===side&&p.id!==side*11){let q=Math.hypot(p.x-x,p.y-y);if(q<d){best=p;d=q}}return best}
function controlled(){return players[state.user]||players[1]}
function setOwner(p){ball.owner=p.id;ball.lastSide=p.side;ball.vx=p.vx*.6;ball.vy=p.vy*.6;}
function action(type){if(!state.playing||state.paused)return;const p=controlled();if(type==='switch'){const candidates=players.filter(q=>q.side===0&&q.id!==0).sort((a,b)=>dist(a,ball)-dist(b,ball));let current=candidates.findIndex(q=>q.id===state.user);state.user=candidates[(current+1)%candidates.length].id;notify('Jogador '+players[state.user].number+' selecionado');return;}if(type==='sprint'){keys.sprint=!keys.sprint;return;}if(type==='pass'||type==='lob'||type==='shoot'){if(ball.owner!==p.id){if(dist(p,ball)<47){setOwner(p)}else if(type!=='shoot'){p.tx=ball.x;p.ty=ball.y;return}else return;}let direction=state.attackDir;let target=null;if(type!=='shoot'){const mates=players.filter(q=>q.side===0&&q.id!==p.id);const aimX=stick.x||direction,aimY=stick.y;target=mates.sort((a,b)=>{const sa=(a.x-p.x)*aimX+(a.y-p.y)*aimY-Math.abs(a.y-p.y)*.17;const sb=(b.x-p.x)*aimX+(b.y-p.y)*aimY-Math.abs(b.y-p.y)*.17;return sb-sa})[0];if(!target||target===p)target=mates.sort((a,b)=>dist(a,ball)-dist(b,ball))[0];}
const targetX=type==='shoot'?(direction>0?field.x+field.w+80:field.x-80):(target?.x??p.x+direction*300);const targetY=type==='shoot'?field.y+field.h*(.5+rand(-.18,.18)):(target?.y??p.y);const dx=targetX-p.x,dy=targetY-p.y,len=Math.hypot(dx,dy)||1;const power=type==='shoot'?Math.min(14,8+p.shot/17):type==='lob'?11:8;ball.owner=null;ball.x=p.x+p.vx*2;ball.y=p.y+p.vy*2;ball.vx=dx/len*power;ball.vy=dy/len*power;ball.z=type==='lob'?9:0;ball.vz=type==='lob'?8:type==='shoot'?1.5:0;ball.lastSide=0;if(type==='shoot'){state.shots[0]++;announce('Finalização!')}else{announce(type==='lob'?'Lançamento!':'Passe!')}p.cool=.4;return;}
if(type==='tackle'){const opp=players.filter(q=>q.side===1).sort((a,b)=>dist(a,p)-dist(b,p))[0];if(opp&&dist(opp,p)<65&&ball.owner===opp.id){if(Math.random()<.78){setOwner(p);announce('Desarme limpo!')}else{state.fouls[1]++;opp.cool=1;announce('Falta!');if(Math.random()<.12)opp.yellow++}}else{p.vx+=stick.x*3;p.vy+=stick.y*3;p.cool=.65;}}}
function goal(side){state.score[side]++;goalFlash=1;ball.owner=null;ball.vx=ball.vy=ball.vz=0;ball.x=field.x+field.w/2;ball.y=field.y+field.h/2;for(const p of players){let spot=formations[state.formation][p.id%11];p.x=field.x+(p.side?field.w*(1-spot[0]):field.w*spot[0]);p.y=field.y+field.h*spot[1];p.vx=p.vy=0;}announce(side===0?'GOOOOL DO AZURE!':'Gol do Rubro!');if(state.score[side]>=5)notify('Que goleada!');}
function restart(kind,side){ball.owner=null;ball.vx=ball.vy=0;ball.z=ball.vz=0;if(kind==='Gol') {ball.x=field.x+field.w/2;ball.y=field.y+field.h/2;}else if(kind==='Escanteio'){ball.x=side===0?field.x+field.w:field.x;ball.y=ball.y<field.y+field.h/2?field.y+5:field.y+field.h-5;announce('Escanteio!')}else{ball.x=clamp(ball.x,field.x+5,field.x+field.w-5);ball.y=clamp(ball.y,field.y+5,field.y+field.h-5);announce(kind+'!')}const p=nearest(side,ball.x,ball.y);if(p){p.tx=ball.x;p.ty=ball.y;setTimeout(()=>{if(ball.owner===null&&state.playing&&dist(p,ball)<80)setOwner(p)},500)}}
function update(dt){if(!state.playing||state.paused)return;state.time+=dt;const duration=state.mode==='training'?1e8:state.duration;if(state.time>=duration){finish();return}if(state.time>duration*.48&&!state.halftime){state.halftime=true;announce('Intervalo!');}if(state.time>duration)state.time=duration;const aim={x:stick.x,y:stick.y},user=controlled();if(stick.active){user.tx=clamp(user.x+aim.x*140,field.x+10,field.x+field.w-10);user.ty=clamp(user.y+aim.y*140,field.y+10,field.y+field.h-10)}
for(const p of players){const side=p.side,atk=side===0?1:-1;const team=teamAt(side?state.away:state.home);let formation=side?(team.formation||state.formation):state.formation;let spot=formations[formation][p.id%11];let homeX=side?field.x+field.w*(1-spot[0]):field.x+field.w*spot[0];let homeY=field.y+field.h*spot[1];let bside=ball.x<field.x+field.w/2?0:1;const attacking=side===0?bside===0:bside===1;let tx=homeX,ty=homeY;
if(p.id===state.user){tx=stick.active?clamp(p.x+aim.x*135,field.x+5,field.x+field.w-5):p.tx;ty=stick.active?clamp(p.y+aim.y*135,field.y+5,field.y+field.h-5):p.ty;if(ball.owner===p.id){tx=p.x+atk*170;ty=p.y+(aim.y||Math.sin(performance.now()/700)*.2)*120}}
else if(p.id===side*11){const goalX=side?field.x+field.w-18:field.x+18;tx=goalX+clamp((ball.x-goalX)*.12,-80,80);ty=clamp(ball.y,field.y+field.h*.28,field.y+field.h*.72);if(Math.abs(ball.x-goalX)<220){tx=goalX+atk*25;ty=clamp(ball.y,field.y+field.h*.36,field.y+field.h*.64)}if(ball.owner===p.id){tx=goalX+atk*80;}}
else if(ball.owner===p.id){tx=p.x+atk*180;ty=p.y+Math.sin(performance.now()/500+p.id)*20}
else if(ball.owner!==null&&players[ball.owner]?.side!==side){let opponents=players.filter(q=>q.side!==side&&q.id!==q.side*11).sort((a,b)=>dist(a,ball)-dist(b,ball));let marker=opponents[0];let cover=opponents[1];if(marker?.id===p.id){tx=ball.x-atk*30;ty=ball.y+(p.y-ball.y)*.25}else if(cover?.id===p.id){tx=ball.x-atk*130;ty=ball.y+(p.y-ball.y)*.7}else{tx=homeX+(ball.x-(field.x+field.w/2))*.18;ty=homeY+(ball.y-(field.y+field.h/2))*.12}}
else if(ball.owner!==null&&players[ball.owner]?.side===side){if(side===0&&p.id!==state.user&&Math.abs(p.y-ball.y)<220){tx=clamp(homeX+atk*100,field.x+20,field.x+field.w-20);ty=homeY+(ball.y-homeY)*.18;}else{tx=homeX+(ball.x-(field.x+field.w/2))*.12;ty=homeY+(ball.y-(field.y+field.h/2))*.08}}
else{tx=homeX+(ball.x-(field.x+field.w/2))*.17;ty=homeY+(ball.y-(field.y+field.h/2))*.15;if(p.id===nearest(side).id){tx=ball.x;ty=ball.y}}
p.tx=clamp(tx,field.x+8,field.x+field.w-8);p.ty=clamp(ty,field.y+8,field.y+field.h-8);
const dx=p.tx-p.x,dy=p.ty-p.y,d=Math.hypot(dx,dy);let pace=(p.pace/80)*(p.stamina<20?.66:1)*(p.id===state.user&&keys.sprint?1.5:1);const max=(p.id===side*11?2.45:2.7)*pace;if(d>3){p.vx+=(dx/d*max-p.vx)*Math.min(1,dt*4);p.vy+=(dy/d*max-p.vy)*Math.min(1,dt*4)}else{p.vx*=.8;p.vy*=.8}if(p.id===state.user&&keys.sprint&&d>8)p.stamina=Math.max(0,p.stamina-dt*9);else p.stamina=Math.min(100,p.stamina+dt*2);p.x=clamp(p.x+p.vx*dt*60,field.x-5,field.x+field.w+5);p.y=clamp(p.y+p.vy*dt*60,field.y-5,field.y+field.h+5);
if(ball.owner===null&&dist(p,ball)<19&&ball.z<10){if(side===0&&p.id===state.user||side===1&&Math.random()<.12||side===0&&Math.random()<.22){setOwner(p)}}}
if(ball.owner!==null){const p=players[ball.owner];if(p){ball.x=p.x+(p.vx*2);ball.y=p.y+14+Math.sin(performance.now()/120)*2;ball.vx=p.vx;ball.vy=p.vy;ball.z=Math.max(0,ball.z-dt*8);state.possession[p.side]+=dt}}
else{ball.x+=ball.vx*dt*60;ball.y+=ball.vy*dt*60;ball.vx*=Math.pow(.985,dt*60);ball.vy*=Math.pow(.985,dt*60);ball.z+=ball.vz*dt*60;ball.vz-=.45*dt*60;if(ball.z<0){ball.z=0;ball.vz=Math.abs(ball.vz)*.42;ball.vx*=.86;ball.vy*=.86;if(Math.abs(ball.vz)<1)ball.vz=0}
for(const p of players){if(p.id===0||p.id===11)continue;let d=dist(p,ball);if(d<17&&ball.z<10){const isUser=p.id===state.user;if(isUser||Math.random()<.12){setOwner(p);break}else{ball.vx+=(ball.x-p.x)*.04;ball.vy+=(ball.y-p.y)*.04}}}}
// Player-to-player body collisions
for(let i=1;i<players.length;i++)for(let j=i+1;j<players.length;j++){let a=players[i],b=players[j];if(a.side===b.side)continue;let dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy);if(d>0&&d<19){let push=(19-d)*.5;a.x-=dx/d*push;a.y-=dy/d*push;b.x+=dx/d*push;b.y+=dy/d*push;if(ball.owner===a.id||ball.owner===b.id){if(Math.random()<.002){state.fouls[ball.owner===a.id?0:1]++;announce('Falta no meio-campo')}}}}
